const fs=require('node:fs'),cp=require('node:child_process'),p=require('node:path'),z=require('node:zlib');const list=cp.execFileSync('git',['diff','--cached','--name-only'],{encoding:'utf8'}).trim().split('
').filter(x=>x.endsWith('.md')||x.endsWith('.md.gz'));const manifest=JSON.parse(fs.readFileSync('docs/coordinator/worktree-completion/evidence/dcc1-closeout-manifest.json'));const archives=new Map([...manifest.entries,...manifest.old40].map(e=>[e.original.path,e.archive.path]));const missing=[],archived=[],direct=[];for(const file of list){const txt=file.endsWith('.gz')?z.gunzipSync(fs.readFileSync(file)).toString():fs.readFileSync(file,'utf8');const logical=file.endsWith('.gz')?file.slice(0,-3):file;for(const m of txt.matchAll(/\[[^\]
]*\]\(([^)
]+)\)/g)){let target=m[1].replace(/^<|>$/g,'');if(/^(https?:|#|mailto:)/.test(target))continue;target=target.split('#')[0];if(!target)continue;const resolved=p.normalize(p.resolve(p.dirname(logical),target));const relative=p.relative(process.cwd(),resolved);if(archives.has(relative)){archived.push({file,target,resolver:archives.get(relative)});continue;}if(fs.existsSync(resolved))direct.push({file,target});else missing.push({file,target});}}console.log(JSON.stringify({files:list.length,direct:direct.length,archived:archived.length,missing,archiveResolved:archived}));
